package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.security.*;
import java.util.*;

/** Current owner-directed cohort protocol; identities describe the actual open process and pool. */
public final class RatisSnapshotCohortRpc {
    public static final int OWNER=112,CAPTURE=113,STATE=114,CANCEL=115,MAX_MEMBERS=1024,MAX_REQUEST_BYTES=16*1024*1024,MAX_REPLY_BYTES=256*1024,MAX_CAPABILITIES_BYTES=177;
    public record Capabilities(UUID nodeId,UUID nodeIncarnation,UUID processIncarnation,UUID poolId,int maximumCohorts,int currentCohorts,long maximumMetadataBytes,long metadataBytes,
            int registryMaximumEntries,int registryEntries,long registryMaximumBytes,long registryBytes,long maximumReadonlyMillis,int poolMaximumPins,int poolPins,long poolMaximumBytes,long poolBytes,long poolMaximumAgeMillis,long poolNextEstimatedBytes,long poolFreeBytes,long poolMinimumFreeBytes) {
        public Capabilities {Objects.requireNonNull(nodeId);Objects.requireNonNull(nodeIncarnation);Objects.requireNonNull(processIncarnation);Objects.requireNonNull(poolId);if(maximumCohorts<1 || currentCohorts<0 || currentCohorts>maximumCohorts || maximumMetadataBytes<1 || metadataBytes<0 || metadataBytes>maximumMetadataBytes || registryMaximumEntries<1 || registryEntries<0 || registryEntries>registryMaximumEntries || registryMaximumBytes<1 || registryBytes<0 || registryBytes>registryMaximumBytes || maximumReadonlyMillis<1 || maximumReadonlyMillis>RatisSnapshotCaptureRequest.maximumTtl(RatisSnapshotCaptureRequest.Mode.READ_ONLY).toMillis() || poolMaximumPins<1 || poolPins<0 || poolMaximumBytes<1 || poolBytes<0 || poolMaximumAgeMillis<1 || poolNextEstimatedBytes<0 || poolFreeBytes<0 || poolMinimumFreeBytes<0)throw new IllegalArgumentException("Invalid actual cohort capabilities");}
    }
    public record Request(RatisDatabaseBackupJournal.CohortRequest cohort,Map<UUID,RatisSnapshotCaptureRequest> captures) {
        public Request {Objects.requireNonNull(cohort);captures=Map.copyOf(captures);if(captures.size()!=cohort.members().size())throw new IllegalArgumentException("Cohort request coverage changed");var definitions=fences(captures,cohort.members().size());for(var member:cohort.members()){var capture=captures.get(member.groupId());if(capture==null || capture.mode()!=RatisSnapshotCaptureRequest.Mode.READ_ONLY || !capture.fence().fenceId().equals(member.fenceId()) || !capture.owner().equals(member.owner()) || !capture.snapshotId().equals(member.snapshotId()) || capture.ttl().toMillis()!=member.ttlMillis() || !MessageDigest.isEqual(member.preparedDigest(),preparedDigest(capture,definitions.get(capture.fence().fenceId()))))throw new IllegalArgumentException("Cohort changed frozen capture request");capture.fence().participant(member.groupId());}}
    }
    public record Reference(UUID cohortId,UUID nodeIncarnation,UUID processIncarnation,UUID poolId,byte[] digest) {
        public Reference {Objects.requireNonNull(cohortId);Objects.requireNonNull(nodeIncarnation);Objects.requireNonNull(processIncarnation);Objects.requireNonNull(poolId);if(digest.length!=32)throw new IllegalArgumentException("Invalid cohort reference");digest=digest.clone();}
        @Override public byte[] digest(){return digest.clone();}
    }
    public enum Phase { PENDING, CAPTURED, LOST, DRAINING, RELEASED, GONE }
    public record Reply(Reference reference,Phase phase,Map<UUID,RatisSnapshotCaptureRequest.Result> captures) {
        public Reply {Objects.requireNonNull(reference);Objects.requireNonNull(phase);captures=Map.copyOf(captures);if(captures.size()>MAX_MEMBERS || phase!=Phase.CAPTURED && !captures.isEmpty())throw new IllegalArgumentException("Invalid cohort result vector");}
    }
    public static byte[] capabilities(Capabilities c){if(c==null)return new byte[]{0};var b=ByteBuffer.allocate(MAX_CAPABILITIES_BYTES);b.put((byte)1);for(var id:List.of(c.nodeId,c.nodeIncarnation,c.processIncarnation,c.poolId))uuid(b,id);b.putInt(c.maximumCohorts).putInt(c.currentCohorts).putLong(c.maximumMetadataBytes).putLong(c.metadataBytes).putInt(c.registryMaximumEntries).putInt(c.registryEntries).putLong(c.registryMaximumBytes).putLong(c.registryBytes).putLong(c.maximumReadonlyMillis).putInt(c.poolMaximumPins).putInt(c.poolPins).putLong(c.poolMaximumBytes).putLong(c.poolBytes).putLong(c.poolMaximumAgeMillis).putLong(c.poolNextEstimatedBytes).putLong(c.poolFreeBytes).putLong(c.poolMinimumFreeBytes);return Arrays.copyOf(b.array(),b.position());}
    public static Capabilities capabilities(byte[] bytes){if(bytes.length<1 || bytes.length>MAX_CAPABILITIES_BYTES)throw new IllegalArgumentException("Invalid cohort capability length");var b=ByteBuffer.wrap(bytes);int present=b.get()&255;if(present==0){if(b.hasRemaining())throw new IllegalArgumentException("Trailing unsupported capabilities");return null;}if(present!=1 || bytes.length!=MAX_CAPABILITIES_BYTES)throw new IllegalArgumentException("Invalid cohort capability tag/length");var c=new Capabilities(uuid(b),uuid(b),uuid(b),uuid(b),b.getInt(),b.getInt(),b.getLong(),b.getLong(),b.getInt(),b.getInt(),b.getLong(),b.getLong(),b.getLong(),b.getInt(),b.getInt(),b.getLong(),b.getLong(),b.getLong(),b.getLong(),b.getLong(),b.getLong());if(b.hasRemaining() || !Arrays.equals(bytes,capabilities(c)))throw new IllegalArgumentException("Noncanonical cohort capabilities");return c;}
    public static byte[] request(Request request){try {
        var fences=fences(request.captures,request.cohort.members().size());long size=72L+124L*request.cohort.members().size();for(var encoded:fences.values())size+=4L+encoded.length;
        var indexes=new HashMap<UUID,Integer>();int next=0;for(var id:fences.keySet())indexes.put(id,next++);var bytes=new ByteArrayOutputStream((int)size);var out=new DataOutputStream(bytes);var c=request.cohort;for(var id:List.of(c.cohortId(),c.nodeIncarnation(),c.processIncarnation(),c.poolId()))uuid(out,id);out.writeInt(fences.size());for(var encoded:fences.values()){out.writeInt(encoded.length);out.write(encoded);}out.writeInt(c.members().size());for(var m:c.members()){for(var id:List.of(m.fenceId(),m.groupId(),m.snapshotId(),m.owner(),m.replica()))uuid(out,id);out.writeLong(m.ttlMillis());out.write(m.preparedDigest());out.writeInt(indexes.get(m.fenceId()));}out.flush();return bytes.toByteArray();
        }catch(IOException impossible){throw new AssertionError(impossible);}}
    public static Request request(byte[] bytes){if(bytes.length>MAX_REQUEST_BYTES-ScopedTransactionRpc.HEADER_BYTES)throw new IllegalArgumentException("Cohort request exceeds frame budget");try {
        var in=new DataInputStream(new ByteArrayInputStream(bytes));var cohort=uuid(in);var node=uuid(in);var process=uuid(in);var pool=uuid(in);int definitions=in.readInt();if(definitions<1 || definitions>MAX_MEMBERS || definitions>in.available()/4)throw new IllegalArgumentException("Invalid cohort dictionary count");var fences=new ArrayList<SnapshotFence>();UUID prior=null;for(int n=0;n<definitions;n++){int length=in.readInt();if(length<SnapshotFence.HEADER_BYTES || length>SnapshotFence.MAX_BYTES || length>in.available())throw new IllegalArgumentException("Invalid cohort definition size");var fence=SnapshotFence.decode(in.readNBytes(length));if(prior!=null && RangeDirectoryCodec.UUID_ORDER.compare(prior,fence.fenceId())>=0)throw new IllegalArgumentException("Noncanonical cohort dictionary");fences.add(fence);prior=fence.fenceId();}
        int count=in.readInt();if(count<1 || count>MAX_MEMBERS || in.available()!=count*124)throw new IllegalArgumentException("Invalid cohort member count");var members=new ArrayList<RatisDatabaseBackupJournal.Member>();var captures=new HashMap<UUID,RatisSnapshotCaptureRequest>();for(int n=0;n<count;n++){var fenceId=uuid(in);var group=uuid(in);var snapshot=uuid(in);var owner=uuid(in);var replica=uuid(in);long ttl=in.readLong();byte[] digest=in.readNBytes(32);int index=in.readInt();if(index<0 || index>=fences.size() || !fences.get(index).fenceId().equals(fenceId))throw new IllegalArgumentException("Cohort dictionary reference changed");members.add(new RatisDatabaseBackupJournal.Member(fenceId,group,snapshot,owner,replica,ttl,digest));if(captures.put(group,new RatisSnapshotCaptureRequest(fences.get(index),owner,snapshot,java.time.Duration.ofMillis(ttl)))!=null)throw new IllegalArgumentException("Duplicate cohort group");}var result=new Request(new RatisDatabaseBackupJournal.CohortRequest(cohort,node,process,pool,members),captures);if(in.available()!=0 || !Arrays.equals(bytes,request(result)))throw new IllegalArgumentException("Noncanonical cohort request");return result;
        }catch(IOException invalid){throw new IllegalArgumentException("Truncated cohort request",invalid);}}
    public static byte[] cohort(RatisDatabaseBackupJournal.CohortRequest c){try{var bytes=new ByteArrayOutputStream(68+c.members().size()*120);var out=new DataOutputStream(bytes);for(var id:List.of(c.cohortId(),c.nodeIncarnation(),c.processIncarnation(),c.poolId()))uuid(out,id);out.writeInt(c.members().size());for(var m:c.members()){for(var id:List.of(m.fenceId(),m.groupId(),m.snapshotId(),m.owner(),m.replica()))uuid(out,id);out.writeLong(m.ttlMillis());out.write(m.preparedDigest());}out.flush();return bytes.toByteArray();}catch(IOException impossible){throw new AssertionError(impossible);}}
    public static Reference reference(Request request){var c=request.cohort;return new Reference(c.cohortId(),c.nodeIncarnation(),c.processIncarnation(),c.poolId(),hash(cohort(c)));}
    public static Reference reference(RatisDatabaseBackupJournal.CohortRequest c){return new Reference(c.cohortId(),c.nodeIncarnation(),c.processIncarnation(),c.poolId(),hash(cohort(c)));}
    public static byte[] reference(Reference r){var b=ByteBuffer.allocate(96);for(var id:List.of(r.cohortId,r.nodeIncarnation,r.processIncarnation,r.poolId))uuid(b,id);return b.put(r.digest).array();}
    public static Reference reference(byte[] bytes){if(bytes.length!=96)throw new IllegalArgumentException("Invalid cohort reference size");var b=ByteBuffer.wrap(bytes);return new Reference(uuid(b),uuid(b),uuid(b),uuid(b),read(b,32));}
    public static byte[] reply(Reply reply){var b=ByteBuffer.allocate(101+reply.captures.size()*64);b.put(reference(reply.reference)).put((byte)reply.phase.ordinal()).putInt(reply.captures.size());for(var entry:reply.captures.entrySet().stream().sorted(Map.Entry.comparingByKey(RangeDirectoryCodec.UUID_ORDER)).toList()){if(entry.getValue().handle()!=null)throw new IllegalArgumentException("Cohort result must be read-only");uuid(b,entry.getKey());ScopedTransactionRpc.snapshotToken(b,entry.getValue().token());}return b.array();}
    public static Reply reply(byte[] bytes,Reference expected){if(bytes.length<101 || bytes.length>MAX_REPLY_BYTES)throw new IllegalArgumentException("Cohort reply exceeds budget");var b=ByteBuffer.wrap(bytes);var ref=reference(read(b,96));if(!Arrays.equals(reference(ref),reference(expected)))throw new IllegalArgumentException("Cohort reply changed exact request");int phase=b.get()&255,count=b.getInt();if(phase>=Phase.values().length || count<0 || count>MAX_MEMBERS || b.remaining()!=count*64)throw new IllegalArgumentException("Invalid cohort reply vector");var result=new HashMap<UUID,RatisSnapshotCaptureRequest.Result>();for(int n=0;n<count;n++)if(result.put(uuid(b),new RatisSnapshotCaptureRequest.Result(ScopedTransactionRpc.snapshotToken(b),null))!=null)throw new IllegalArgumentException("Duplicate cohort reply group");var reply=new Reply(ref,Phase.values()[phase],result);if(!Arrays.equals(bytes,reply(reply)))throw new IllegalArgumentException("Noncanonical cohort reply");return reply;}
    private static NavigableMap<UUID,byte[]> fences(Map<UUID,RatisSnapshotCaptureRequest> captures,int members) {
        var result=new TreeMap<UUID,byte[]>(RangeDirectoryCodec.UUID_ORDER);var original=new HashMap<UUID,SnapshotFence>();long size=72L+124L*members;
        for(var capture:captures.values()){var fence=capture.fence();var same=original.get(fence.fenceId());if(same==fence)continue;byte[] encoded=fence.encode();var previous=result.get(fence.fenceId());if(previous!=null){if(!Arrays.equals(previous,encoded))throw new IllegalArgumentException("Cohort fence identity changed");continue;}size+=4L+encoded.length;if(size>MAX_REQUEST_BYTES-ScopedTransactionRpc.HEADER_BYTES)throw new IllegalArgumentException("Cohort dictionary exceeds frame budget");result.put(fence.fenceId(),encoded);original.put(fence.fenceId(),fence);}
        return result;
    }
    private static byte[] preparedDigest(RatisSnapshotCaptureRequest request,byte[] fence) {
        try {var digest=MessageDigest.getInstance("SHA-256");digest.update(ByteBuffer.allocate(ScopedTransactionRpc.HEADER_BYTES).putInt(ScopedTransactionRpc.MAGIC).putInt(ScopedTransactionRpc.SNAPSHOT_CAPTURE).putInt(RatisSnapshotCaptureRequest.HEADER_BYTES+fence.length).array());var header=ByteBuffer.allocate(RatisSnapshotCaptureRequest.HEADER_BYTES);uuid(header,request.owner());uuid(header,request.snapshotId());header.putLong(request.ttl().toMillis()).put((byte)0).putInt(fence.length);digest.update(header.array());digest.update(fence);return digest.digest();}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}
    }
    static byte[] hash(byte[] bytes){try{return MessageDigest.getInstance("SHA-256").digest(bytes);}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
    private static byte[] read(ByteBuffer b,int size){byte[] bytes=new byte[size];b.get(bytes);return bytes;}
    private static void uuid(ByteBuffer b,UUID id){b.putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits());}
    private static UUID uuid(ByteBuffer b){return new UUID(b.getLong(),b.getLong());}
    private static void uuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}
    private static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
}
